import { readFileSync } from "node:fs"
import { join } from "node:path"

export const dynamic = "force-static"

const raw = "https://raw.githubusercontent.com/WatermelonBros/rind-ui/main/docs"
const site = "https://rind.watermelon-studio.it"

/**
 * /llms.txt: generated by scripts/content.ts, served where assistants look for it. Its links are
 * repo-relative, so they point at the raw markdown on GitHub here; the token reference is not
 * committed, so it points at this site's /theme/tokens.md.
 */
export function GET() {
  const text = readFileSync(join(process.cwd(), "content/generated/llms.txt"), "utf8")
    .replace("](docs/theme/tokens.md)", "](https://rind.watermelon-studio.it/theme/tokens.md)")
    // components and guides: the site's own markdown twins (scripts/content.ts)
    .replace(/\]\(docs\/(?:components|guides)\/([\w-]+\.md)\)/g, `](${site}/docs/$1)`)
    .replace(/\]\(docs\/([^)]+)\)/g, `](${raw}/$1)`)
    .replace(/\]\(\.\.\/(components|guides)\/([^)]+)\)/g, `](${raw}/$1/$2)`)
  const optional = `
## Optional

- [Full documentation](${site}/llms-full.txt): every page above in one file.
- [Agent skill](https://github.com/WatermelonBros/rind-ui/tree/main/skills/rind-ui): how to compose rind-ui and verify it with the drivers, in the Agent Skills format.
- [rind-ui compared](${site}/compare.md): how rind-ui differs from other headless libraries, where they are ahead, and when to pick them instead.
`
  return new Response(`${text.trimEnd()}\n${optional}`, {
    headers: { "content-type": "text/plain; charset=utf-8" },
  })
}
